def full_rows_cols(grid):
    """Indices of rows and of columns that are a single color throughout."""
    rows={i for i,row in enumerate(grid) if len(set(row))==1}
    cols={j for j in range(len(grid[0])) if len({row[j] for row in grid})==1}
    return rows,cols

def recolor_full_lines(grid, new=2):
    """Cells on rows or columns that are one color throughout become new (line cells)."""
    rows,cols=full_rows_cols(grid)
    return [[new if (i in rows or j in cols) else v for j,v in enumerate(row)]
